<?php superOnly();if(!usernamesReady()):?><section class="panel"><h1>Korisnici</h1><p>Prvo napravite backup i primijenite <strong>database/migrations/014_usernames.sql</strong> u postojeću bazu.</p></section><?php return;endif;$edit=query('SELECT id,name,username,email,role_id,active FROM users WHERE id=?',[(int)($_GET['id']??0)])->fetch()?:[];?>
<h1>Korisnici</h1><section class="panel"><?php startForm('user',(int)($edit['id']??0));field('name','Ime',$edit['name']??'');?><label for="username">Korisničko ime za prijavu</label><input id="username" name="username" value="<?=e($edit['username']??'')?>" type="text" minlength="3" maxlength="64" autocomplete="username" autocapitalize="none" spellcheck="false" required><p>3–64 znaka: slova a–z, brojevi, tačka, crtice. Korisničko ime je jedinstveno među administratorima i zaposlenicima.</p><?php field('email','Kontakt e-mail',$edit['email']??'','email');field('password','Lozinka (12–72 bajta; prazno zadržava postojeću)','','password',!$edit);$options=[];foreach(query('SELECT * FROM roles ORDER BY id')->fetchAll() as $r)$options[$r['id']]=$r['name'];selectField('role_id','Uloga',$options,$edit['role_id']??1);?><label><input type="checkbox" name="active" <?=!$edit||$edit['active']?'checked':''?>> Aktivan</label><button>Spremi korisnika</button></form></section>
<section class="panel"><div class="table-scroll"><table><thead><tr><th>Ime</th><th>Korisničko ime</th><th>Kontakt e-mail</th><th>Uloga / status</th></tr></thead><tbody><?php foreach(query('SELECT u.*,r.name role_name FROM users u JOIN roles r ON r.id=u.role_id ORDER BY u.name')->fetchAll() as $usr):?><tr><td><a href="?page=users&amp;id=<?=(int)$usr['id']?>"><?=e($usr['name'])?></a></td><td><strong><?=e((string)$usr['username'])?></strong></td><td><?=e($usr['email'])?></td><td><?=e($usr['role_name'])?> · <?=$usr['active']?'Aktivan':'Isključen'?></td></tr><?php endforeach;?></tbody></table></div></section>
